package com.g4t0xx.forge;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
final class ChatStore extends SQLiteOpenHelper {
 ChatStore(Context c){super(c,"assistant.db",null,1);setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE threads(id TEXT PRIMARY KEY,title TEXT,created INTEGER)");d.execSQL("CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,thread TEXT,role TEXT,text TEXT,created INTEGER)");d.execSQL("CREATE INDEX message_thread ON messages(thread,id)");d.execSQL("CREATE TABLE memory(id TEXT PRIMARY KEY,text TEXT,source TEXT,updated INTEGER)");d.execSQL("CREATE TABLE jobs(id TEXT PRIMARY KEY,thread TEXT,data TEXT)");d.execSQL("CREATE TABLE actions(id TEXT PRIMARY KEY,data TEXT)");}
 public void onUpgrade(SQLiteDatabase d,int a,int b){}
 synchronized String thread(String title){String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("title",title.substring(0,Math.min(70,title.length())));v.put("created",System.currentTimeMillis());getWritableDatabase().insertOrThrow("threads",null,v);return id;}
 synchronized long message(String t,String role,String text){ContentValues v=new ContentValues();v.put("thread",t);v.put("role",role);v.put("text",text);v.put("created",System.currentTimeMillis());return getWritableDatabase().insertOrThrow("messages",null,v);}
 synchronized JSONArray query(String sql,String...args)throws Exception{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext()){JSONObject j=new JSONObject();for(int i=0;i<c.getColumnCount();i++)j.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getString(i));a.put(j);}}return a;}
 JSONArray threads()throws Exception{return query("SELECT * FROM threads ORDER BY created DESC");}
 JSONArray messages(String t)throws Exception{return query("SELECT * FROM messages WHERE thread=? ORDER BY id",t);}
 JSONArray memories()throws Exception{return query("SELECT * FROM memory WHERE source != 'deleted' ORDER BY updated DESC");}
 synchronized void remember(String id,String text,String source){ContentValues v=new ContentValues();v.put("id",id);v.put("text",text);v.put("source",source);v.put("updated",System.currentTimeMillis());getWritableDatabase().insertWithOnConflict("memory",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 synchronized void forget(String id){ContentValues v=new ContentValues();v.put("text","");v.put("source","deleted");v.put("updated",System.currentTimeMillis());getWritableDatabase().update("memory",v,"id=?",new String[]{id});}
 synchronized void mergeMemory(JSONObject m)throws Exception{JSONArray previous=query("SELECT updated FROM memory WHERE id=?",m.getString("id"));if(previous.length()>0&&Long.parseLong(previous.getJSONObject(0).getString("updated"))>m.optLong("updated"))return;ContentValues v=new ContentValues();v.put("id",m.getString("id"));v.put("text",m.getString("text"));v.put("source",m.optString("source","sincronizado"));v.put("updated",m.optLong("updated",System.currentTimeMillis()));getWritableDatabase().insertWithOnConflict("memory",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 synchronized void mergeExport(JSONObject data)throws Exception{
  SQLiteDatabase db=getWritableDatabase();db.execSQL("CREATE TABLE IF NOT EXISTS imported_messages(id TEXT PRIMARY KEY)");JSONArray threads=data.optJSONArray("threads");if(threads!=null)for(int i=0;i<threads.length();i++){JSONObject t=threads.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",t.getString("id"));v.put("title",t.getString("title"));v.put("created",t.optLong("created"));db.insertWithOnConflict("threads",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
  JSONArray messages=data.optJSONArray("messages");if(messages!=null)for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);String thread=m.getString("thread"),role=m.getString("role"),text=m.getString("text");long created=m.optLong("created");try(Cursor c=db.rawQuery("SELECT 1 FROM messages WHERE thread=? AND role=? AND text=? AND created=? LIMIT 1",new String[]{thread,role,text,String.valueOf(created)})){if(c.moveToFirst())continue;}ContentValues v=new ContentValues();v.put("thread",thread);v.put("role",role);v.put("text",text);v.put("created",created);db.insertOrThrow("messages",null,v);}
 }
 synchronized void job(JSONObject j)throws Exception{ContentValues v=new ContentValues();v.put("id",j.getString("id"));v.put("thread",j.getString("thread"));v.put("data",j.toString());getWritableDatabase().insertWithOnConflict("jobs",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 synchronized JSONObject job(String id)throws Exception{JSONArray a=query("SELECT data FROM jobs WHERE id=?",id);if(a.length()==0)throw new Exception("Tarefa não encontrada");return new JSONObject(a.getJSONObject(0).getString("data"));}
 synchronized JSONArray jobs()throws Exception{JSONArray a=query("SELECT data FROM jobs ORDER BY rowid DESC LIMIT 100"),b=new JSONArray();for(int i=0;i<a.length();i++)b.put(new JSONObject(a.getJSONObject(i).getString("data")));return b;}
 synchronized JSONObject action(String id)throws Exception{JSONArray a=query("SELECT data FROM actions WHERE id=?",id);return a.length()==0?null:new JSONObject(a.getJSONObject(0).getString("data"));}
 synchronized void action(String id,JSONObject j){ContentValues v=new ContentValues();v.put("id",id);v.put("data",j.toString());getWritableDatabase().insertWithOnConflict("actions",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 String context(String thread,String prompt)throws Exception{
  StringBuilder b=new StringBuilder("MEMÓRIAS PESSOAIS CONFIRMADAS DO USUÁRIO (use estes fatos, não invente):\n");JSONArray memories=query("SELECT * FROM memory WHERE source != 'deleted' ORDER BY CASE WHEN id='perfil-principal' THEN 0 WHEN source LIKE 'perfil%' THEN 1 WHEN source LIKE 'preferencia%' THEN 2 ELSE 3 END, updated DESC");Set<String> words=new HashSet<>(Arrays.asList(prompt.toLowerCase(Locale.ROOT).split("\\W+")));
  for(int i=0;i<memories.length();i++){JSONObject m=memories.getJSONObject(i);String text=m.getString("text");boolean relevant=m.getString("source").startsWith("perfil")||m.getString("source").startsWith("preferencia");for(String w:words)if(w.length()>3&&text.toLowerCase(Locale.ROOT).contains(w))relevant=true;if(relevant&&b.length()<2500)b.append(text).append('\n');}
  JSONArray rows=messages(thread);b.append("\nCONVERSA RECENTE:\n");for(int i=Math.max(0,rows.length()-6);i<rows.length();i++){JSONObject m=rows.getJSONObject(i);String text=m.getString("text");b.append(m.getString("role")).append(": ").append(text.substring(0,Math.min(650,text.length()))).append('\n');}
  // Older messages remain in SQLite and can be searched with search_history.
  JSONArray old=search(prompt.length()>40?prompt.split(" ")[0]:prompt);if(old.length()>0)b.append("\nREGISTROS ANTIGOS RELEVANTES:\n").append(old.toString().substring(0,Math.min(2500,old.toString().length())));return b.toString().substring(0,Math.min(7500,b.length()));
 }
 JSONArray search(String term)throws Exception{return query("SELECT role,text,thread FROM messages WHERE text LIKE ? ORDER BY id DESC LIMIT 12","%"+term.replace("%","")+"%");}
 JSONObject exportData()throws Exception{return Json.obj("schema",1,"threads",threads(),"messages",query("SELECT * FROM messages ORDER BY id"),"memory",query("SELECT * FROM memory"),"jobs",jobs());}
}
